local characters={"Rivet","Pip","Moss"};local topics={}
for index,row in ipairs(rows)do local id,category,question,claim=table.unpack(row);topics[index]={Id=id,Category=category,Character=characters[((index-1)%3)+1],Proposition=claim,Topic=question,Sides={Affirmative={Id="affirmative",Label="FOR",Position=claim,OpeningPrompt="Open FOR by giving one reason that "..string.lower(claim).." Add a concrete example."},Negative={Id="negative",Label="AGAINST",Position="Oppose this claim: "..claim,OpeningPrompt="Open AGAINST by explaining one cost, exception, or better alternative to: "..string.lower(claim)}},ScriptedOpening="Rivet, Pip and Moss assigned one player to each side. The scripted panel tracks visible writing features only; it does not judge which argument is true or stronger.",TurnPrompts=prompts}end
Bank.Topics=table.freeze(topics)
function Bank.Offers(seed)local first=((math.max(1,math.floor(seed or 1))-1)*3)%#topics+1;return {topics[first],topics[first%#topics+1],topics[(first+1)%#topics+1]}end
function Bank.FindInOffers(offers,id)for _,topic in ipairs(offers or {})do if topic.Id==id then return topic end end end
function Bank.Summary(offers)local result={};for _,topic in ipairs(offers)do table.insert(result,{Id=topic.Id,Topic=topic.Topic,Category=topic.Category})end;return result end
return Bank
